app<-source("app.R")$value
checks<-0L
check<-function(ok,label){if(!isTRUE(ok))stop("FAIL: ",label,call.=FALSE);checks<<-checks+1L;cat("PASS:",label,"\n")}
shiny::testServer(app,{
  # Explicit fixture: production startup is intentionally empty.
  raw(pc_example("column")$table);sheet_name("Treatment groups");project_name("Example study");document_open(TRUE)
 do.call(session$setInputs,pc_defaults());session$flushReact()
 original<-raw();original_settings<-settings()
 session$setInputs(new_view_name="Distribution and ANOVA",confirm_new_view=1);session$flushReact()
 check(active_view()=="V2" && length(view_book())==2,"creating a linked view retains the primary view")
 session$setInputs(method="anova",graph="box",title="Distribution",legend_position="bottom",grid_lines=TRUE,y_min="0",y_max="35");session$flushReact()
 anova_before<-analysis_state()$value$p
 check(analysis_state()$value$method=="anova","linked view uses its own selected analysis")
 session$setInputs(graph_view="V1");session$flushReact();do.call(session$setInputs,views()[[active_view()]]$settings);session$flushReact()
 check(settings()$method==original_settings$method && settings()$graph==original_settings$graph,"switching views restores the original analysis and graph")
 check(settings()$title==original_settings$title && settings()$legend_position=="auto" && !settings()$grid_lines,"switching views restores independent formatting")
 check(identical(raw(),original),"view switches do not duplicate or replace source observations")
 session$setInputs(data_grid_cell_edit=list(row=1,col=0,value="35"));session$flushReact()
 session$setInputs(graph_view="V2");session$flushReact();do.call(session$setInputs,views()[[active_view()]]$settings);session$flushReact()
 check(raw()[1,1]=="35" && analysis_state()$value$p!=anova_before,"a source edit updates the other view’s analysis")
 check(settings()$y_max=="35" && settings()$legend_position=="bottom","custom axes and legend persist in the alternate view")
 session$setInputs(layout_views=c("D1:V1","D1:V2"),layout_title="Comparison figure",layout_columns="2",layout_width=180,layout_height=100,layout_dpi="300");session$flushReact()
 check(inherits(layout_grob(),"grob"),"layout preview builds from the active worksheet’s linked views")
 check(nrow(catalog())==2,"view gallery lists both linked presentations")
 session$setInputs(rename_view_name="Distribution summary",confirm_rename_view=1);session$flushReact()
 check(workbook()$D1$views$V2$name=="Distribution summary","renaming a linked view persists in the workbook")
 pc_write_project(snapshot(),"artifacts/views/reactive-linked.rdatacraft")
 p<-pc_load_project("artifacts/views/reactive-linked.rdatacraft")
 check(p$worksheets$D1$active_view=="V2" && p$figure_layout$title=="Comparison figure","snapshot saves active view and figure layout")
 session$setInputs(desktop_saved=list(path=normalizePath("artifacts/views/reactive-linked.rdatacraft"),nonce=1));session$flushReact()
 check(identical(signature(),saved_signature()),"saving views and layout clears the native edited state")
 session$setInputs(worksheet_name="Second experiment",worksheet_layout="xy",worksheet_example=TRUE,confirm_worksheet=1);session$flushReact();do.call(session$setInputs,pending());session$flushReact()
 check(length(view_book())==1 && active_view()=="V1","new worksheets begin with their own primary view")
 session$setInputs(worksheet="D1");session$flushReact();do.call(session$setInputs,views()[[active_view()]]$settings);session$flushReact()
 check(active_view()=="V2" && length(view_book())==2,"returning to a worksheet restores its linked views")
 session$setInputs(layout_title="Unsaved layout edit");session$flushReact()
 check(!identical(signature(),saved_signature()),"layout edits mark the project unsaved")
 session$setInputs(desktop_open_project=list(path=normalizePath("artifacts/views/reactive-linked.rdatacraft"),nonce=2));session$flushReact()
 do.call(session$setInputs,views()[[active_view()]]$settings)
 session$setInputs(layout_views=p$figure_layout$selected,layout_title=p$figure_layout$title,layout_columns=as.character(p$figure_layout$columns),layout_width=p$figure_layout$width,layout_height=p$figure_layout$height,layout_dpi=as.character(p$figure_layout$dpi));session$flushReact()
 check(identical(signature(),saved_signature()),"reopening restores clean view/layout state")
 check(active_view()=="V2" && settings()$method=="anova" && length(layout_settings()$selected)==2,"reopening retains analysis selection and both layout panels")
 check(raw()[1,1]=="35","source edits persist once for all linked views")
 session$setInputs(y_min="unfinished limit");session$flushReact()
 check(document_dirty() && is.null(signature_state()$value),"invalid axis entry still marks the native document unsaved")
 session$setInputs(data_grid_cell_edit=list(row=1,col=0,value="36"));session$flushReact()
 check(raw()[1,1]=="36" && document_dirty(),"source edits remain tracked while an axis entry is invalid")
 session$setInputs(y_min="0");session$flushReact()
 check(!is.null(signature_state()$value) && document_dirty(),"fixing an axis entry retains the unsaved source edit")
})
cat("\n",checks," linked reactive workflow checks passed.\n",sep="")
